-- Ypsilon — keybinds (SUPER-based). Validate with: scripts/check.sh
-- The `description` flag on each bind is what the cheatsheet (SUPER+K) shows — keep it human.
-- Nested preview (`ypsilon try`) sets YPSILON_TRY_MOD so the outer session keeps SUPER.
local P = require("generated.paths")
local Y = P.YPSILON
local MOD = os.getenv("YPSILON_TRY_MOD") or "SUPER"

-- --- shell ---
hl.bind(MOD .. " + Space", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-launcher || fuzzel"), { description = "App launcher & search" })
hl.bind(MOD .. " + C", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-control"), { description = "Control center" })
hl.bind(MOD .. " + SHIFT + C", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-dashboard"), { description = "Dashboard (calendar, stats)" })
hl.bind(MOD .. " + N", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-notif-center"), { description = "Notifications" })
hl.bind(MOD .. " + Tab", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-overview"), { description = "Workspace overview" })
hl.bind(MOD .. " + I", hl.dsp.exec_cmd("ags request -i ypsilon settings"), { description = "Settings" })
hl.bind(MOD .. " + slash", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-cheatsheet"), { description = "This keybind list" })
hl.bind(MOD .. " + SHIFT + W", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-wallpapers"), { description = "Wallpaper picker" })
hl.bind(MOD .. " + X", hl.dsp.exec_cmd(Y .. " wallpaper next"), { description = "Next wallpaper" })
hl.bind(MOD .. " + SHIFT + V", hl.dsp.exec_cmd(Y .. " clip"), { description = "Clipboard history" })
hl.bind(MOD .. " + SHIFT + Q", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-power"), { description = "Power menu" })
hl.bind(MOD .. " + L", hl.dsp.exec_cmd(Y .. " lock"), { description = "Lock screen" })
hl.bind(MOD .. " + Escape", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-power"), { description = "Power menu" })
hl.bind("CTRL + ALT + Delete", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-power"), { description = "Power menu" })
hl.bind(MOD .. " + ALT + R", hl.dsp.exec_cmd(Y .. " reload"), { description = "Reload Hyprland + shell styles" })

-- --- apps ---
hl.bind(MOD .. " + Return", hl.dsp.exec_cmd(Y .. " terminal"), { description = "Terminal (Settings → Apps)" })
hl.bind("CTRL + ALT + T", hl.dsp.exec_cmd(Y .. " terminal"), { description = "Terminal" })
hl.bind(MOD .. " + W", hl.dsp.exec_cmd(Y .. " browser"), { description = "Web browser" })
hl.bind(MOD .. " + E", hl.dsp.exec_cmd("thunar || dolphin || nautilus"), { description = "File manager" })
hl.bind(MOD .. " + ALT + E", hl.dsp.exec_cmd("thunar ~/Downloads || dolphin ~/Downloads || nautilus ~/Downloads"), { description = "Downloads folder" })
hl.bind(MOD .. " + ALT + C", hl.dsp.exec_cmd("code || codium"), { description = "Code editor" })
hl.bind(MOD .. " + SHIFT + Return", hl.dsp.workspace.toggle_special("term"), { description = "Drop-down terminal (show / hide)" })
hl.bind("CTRL + SHIFT + Escape", hl.dsp.workspace.toggle_special("sysmon"), { description = "System monitor (btop)" })

-- --- windows ---
hl.bind(MOD .. " + Q", hl.dsp.window.kill(), { description = "Close window" })
hl.bind("ALT + F4", hl.dsp.window.kill(), { description = "Close window" })
hl.bind(MOD .. " + F", hl.dsp.window.fullscreen(), { description = "Fullscreen" })
hl.bind(MOD .. " + ALT + F", hl.dsp.window.fullscreen({ mode = 1 }), { description = "Maximize (keep bar + gaps)" })
hl.bind(MOD .. " + V", hl.dsp.window.float({ action = "toggle" }), { description = "Float / tile window" })
hl.bind(MOD .. " + SHIFT + P", hl.dsp.window.pin(), { description = "Pin floating window on all workspaces" })
hl.bind(MOD .. " + ALT + backslash", hl.dsp.exec_cmd(Y .. " pip"), { description = "Picture-in-picture (again: back to tiled)" })
hl.bind(MOD .. " + ALT + V", hl.dsp.exec_cmd(Y .. " pip"), { description = "Floating video toggle (again: back to tiled)" })
hl.bind(MOD .. " + ALT + 1", hl.dsp.exec_cmd(Y .. " pip-corner 1"), { description = "Snap floating video top-left (above fullscreen)" })
hl.bind(MOD .. " + ALT + 2", hl.dsp.exec_cmd(Y .. " pip-corner 2"), { description = "Snap floating video top-right (above fullscreen)" })
hl.bind(MOD .. " + ALT + 3", hl.dsp.exec_cmd(Y .. " pip-corner 3"), { description = "Snap floating video bottom-left (above fullscreen)" })
hl.bind(MOD .. " + ALT + 4", hl.dsp.exec_cmd(Y .. " pip-corner 4"), { description = "Snap floating video bottom-right (above fullscreen)" })
hl.bind(MOD .. " + CTRL + backslash", hl.dsp.window.center(), { description = "Center floating window" })
hl.bind(MOD .. " + J", hl.dsp.layout("togglesplit"), { description = "Flip split direction" })
hl.bind(MOD .. " + M", hl.dsp.exec_cmd(Y .. " layout toggle"), { description = "Switch layout (dwindle / master)" })
hl.bind(MOD .. " + T", hl.dsp.group.toggle(), { description = "Group windows into tabs" })
hl.bind(MOD .. " + bracketright", hl.dsp.group.next(), { description = "Next tab in group" })
hl.bind(MOD .. " + bracketleft", hl.dsp.group.prev(), { description = "Previous tab in group" })
hl.bind("ALT + Tab", hl.dsp.window.cycle_next(), { description = "Cycle windows" })
hl.bind("ALT + SHIFT + Tab", hl.dsp.window.cycle_next({ prev = true }), { description = "Cycle windows backwards" })
hl.bind(MOD .. " + U", hl.dsp.focus({ urgent_or_last = true }), { description = "Jump to urgent / last window" })
hl.bind(MOD .. " + left", hl.dsp.focus({ direction = "left" }), { description = "Focus left" })
hl.bind(MOD .. " + right", hl.dsp.focus({ direction = "right" }), { description = "Focus right" })
hl.bind(MOD .. " + up", hl.dsp.focus({ direction = "up" }), { description = "Focus up" })
hl.bind(MOD .. " + down", hl.dsp.focus({ direction = "down" }), { description = "Focus down" })
hl.bind(MOD .. " + SHIFT + left", hl.dsp.window.move({ direction = "left" }), { description = "Move window left" })
hl.bind(MOD .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }), { description = "Move window right" })
hl.bind(MOD .. " + SHIFT + up", hl.dsp.window.move({ direction = "up" }), { description = "Move window up" })
hl.bind(MOD .. " + SHIFT + down", hl.dsp.window.move({ direction = "down" }), { description = "Move window down" })
hl.bind(MOD .. " + ALT + left", hl.dsp.window.swap({ direction = "left" }), { description = "Swap with window left" })
hl.bind(MOD .. " + ALT + right", hl.dsp.window.swap({ direction = "right" }), { description = "Swap with window right" })
hl.bind(MOD .. " + ALT + up", hl.dsp.window.swap({ direction = "up" }), { description = "Swap with window above" })
hl.bind(MOD .. " + ALT + down", hl.dsp.window.swap({ direction = "down" }), { description = "Swap with window below" })
hl.bind(MOD .. " + CTRL + left", hl.dsp.window.resize({ x = -40, y = 0 }), { description = "Narrower" })
hl.bind(MOD .. " + CTRL + right", hl.dsp.window.resize({ x = 40, y = 0 }), { description = "Wider" })
hl.bind(MOD .. " + CTRL + up", hl.dsp.window.resize({ x = 0, y = -40 }), { description = "Shorter" })
hl.bind(MOD .. " + CTRL + down", hl.dsp.window.resize({ x = 0, y = 40 }), { description = "Taller" })
hl.bind(MOD .. " + CTRL + ALT + left", hl.dsp.window.resize({ x = -10, y = 0 }), { repeating = true, description = "Narrower (fine)" })
hl.bind(MOD .. " + CTRL + ALT + right", hl.dsp.window.resize({ x = 10, y = 0 }), { repeating = true, description = "Wider (fine)" })
hl.bind(MOD .. " + CTRL + ALT + up", hl.dsp.window.resize({ x = 0, y = -10 }), { repeating = true, description = "Shorter (fine)" })
hl.bind(MOD .. " + CTRL + ALT + down", hl.dsp.window.resize({ x = 0, y = 10 }), { repeating = true, description = "Taller (fine)" })
hl.bind(MOD .. " + mouse:272", hl.dsp.window.drag(), { mouse = true, description = "Drag to move window" })
hl.bind(MOD .. " + mouse:273", hl.dsp.window.resize(), { mouse = true, description = "Drag to resize window" })
hl.bind(MOD .. " + SHIFT + E", hl.dsp.exit(), { description = "Log out (quit Hyprland)" })

-- --- keyboard-first extras (vim-style + aliases; all searchable in SUPER+K) ---
hl.bind(MOD .. " + ALT + H", hl.dsp.focus({ direction = "left" }), { description = "Focus left (vim)" })
hl.bind(MOD .. " + ALT + J", hl.dsp.focus({ direction = "down" }), { description = "Focus down (vim)" })
hl.bind(MOD .. " + ALT + K", hl.dsp.focus({ direction = "up" }), { description = "Focus up (vim)" })
hl.bind(MOD .. " + ALT + L", hl.dsp.focus({ direction = "right" }), { description = "Focus right (vim)" })
hl.bind(MOD .. " + SHIFT + H", hl.dsp.window.move({ direction = "left" }), { description = "Move window left (vim)" })
hl.bind(MOD .. " + SHIFT + J", hl.dsp.window.move({ direction = "down" }), { description = "Move window down (vim)" })
hl.bind(MOD .. " + SHIFT + K", hl.dsp.window.move({ direction = "up" }), { description = "Move window up (vim)" })
hl.bind(MOD .. " + SHIFT + L", hl.dsp.window.move({ direction = "right" }), { description = "Move window right (vim)" })
hl.bind(MOD .. " + D", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-dashboard"), { description = "Dashboard (calendar, stats)" })
hl.bind(MOD .. " + B", hl.dsp.exec_cmd(Y .. " browser"), { description = "Web browser (alias)" })
hl.bind(MOD .. " + comma", hl.dsp.exec_cmd("ags request -i ypsilon settings"), { description = "Settings (keyboard alias)" })
hl.bind(MOD .. " + K", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-cheatsheet"), { description = "Searchable keybind list" })
hl.bind(MOD .. " + period", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-launcher || fuzzel"), { description = "Launcher (emoji: type .fire)" })
hl.bind(MOD .. " + SHIFT + O", hl.dsp.exec_cmd("ags toggle -i ypsilon ypsilon-overview"), { description = "Workspace overview (alias)" })

