hl.bind(MOD .. " + CTRL + SHIFT + 3", hl.dsp.window.move({ workspace = 3, silent = true }), { description = "Send window to workspace 3 (stay here)" })
hl.bind(MOD .. " + CTRL + SHIFT + 4", hl.dsp.window.move({ workspace = 4, silent = true }), { description = "Send window to workspace 4 (stay here)" })
hl.bind(MOD .. " + CTRL + SHIFT + 5", hl.dsp.window.move({ workspace = 5, silent = true }), { description = "Send window to workspace 5 (stay here)" })
hl.bind(MOD .. " + CTRL + SHIFT + 6", hl.dsp.window.move({ workspace = 6, silent = true }), { description = "Send window to workspace 6 (stay here)" })
hl.bind(MOD .. " + CTRL + SHIFT + 7", hl.dsp.window.move({ workspace = 7, silent = true }), { description = "Send window to workspace 7 (stay here)" })
hl.bind(MOD .. " + CTRL + SHIFT + 8", hl.dsp.window.move({ workspace = 8, silent = true }), { description = "Send window to workspace 8 (stay here)" })
hl.bind(MOD .. " + CTRL + SHIFT + 9", hl.dsp.window.move({ workspace = 9, silent = true }), { description = "Send window to workspace 9 (stay here)" })
hl.bind(MOD .. " + CTRL + SHIFT + 0", hl.dsp.window.move({ workspace = 10, silent = true }), { description = "Send window to workspace 10 (stay here)" })
hl.bind(MOD .. " + grave", hl.dsp.focus({ workspace = "previous" }), { description = "Previous workspace" })
hl.bind(MOD .. " + Page_Down", hl.dsp.focus({ workspace = "e+1" }), { description = "Next workspace" })
hl.bind(MOD .. " + Page_Up", hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace" })
hl.bind(MOD .. " + S", hl.dsp.workspace.toggle_special("magic"), { description = "Scratchpad (show / hide)" })
hl.bind(MOD .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }), { description = "Move window to scratchpad" })
