hl.bind(MOD .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace (scroll)" })

-- --- capture ---
hl.bind("Print", hl.dsp.exec_cmd(Y .. " shot select"), { description = "Screenshot an area" })
hl.bind(MOD .. " + Print", hl.dsp.exec_cmd(Y .. " shot full"), { description = "Screenshot the whole screen" })
hl.bind("CTRL + Print", hl.dsp.exec_cmd(Y .. " shot window"), { description = "Screenshot the active window" })
hl.bind("ALT + Print", hl.dsp.exec_cmd(Y .. " shot delay"), { description = "Screenshot the screen in 3 s (for menus)" })
hl.bind("SHIFT + Print", hl.dsp.exec_cmd(Y .. " shot annotate"), { description = "Screenshot an area and draw on it (satty)" })
hl.bind(MOD .. " + SHIFT + T", hl.dsp.exec_cmd(Y .. " ocr"), { description = "Copy text from the screen (OCR)" })
hl.bind(MOD .. " + SHIFT + R", hl.dsp.exec_cmd(Y .. " record toggle"), { description = "Record an area (again to stop)" })
hl.bind(MOD .. " + P", hl.dsp.exec_cmd(Y .. " pick"), { description = "Color picker" })

-- --- system ---
hl.bind(MOD .. " + SHIFT + G", hl.dsp.exec_cmd(Y .. " gamemode toggle"), { description = "Game mode (max performance)" })
hl.bind(MOD .. " + SHIFT + N", hl.dsp.exec_cmd(Y .. " nightlight toggle"), { description = "Night light" })
hl.bind(MOD .. " + ALT + minus", hl.dsp.exec_cmd(Y .. " gamma lower"), { repeating = true, description = "Gamma down (dims past the backlight minimum)" })
hl.bind(MOD .. " + ALT + equal", hl.dsp.exec_cmd(Y .. " gamma raise"), { repeating = true, description = "Gamma up" })
hl.bind(MOD .. " + ALT + 0", hl.dsp.exec_cmd(Y .. " gamma reset"), { description = "Gamma back to 100%" })
hl.bind(MOD .. " + ALT + G", hl.dsp.exec_cmd(Y .. " gamma toggle"), { description = "Gamma dim on/off" })
hl.bind(MOD .. " + ALT + M", hl.dsp.exec_cmd(Y .. " menu"), { description = "Quick menu (screen, theme, sound toggles)" })
hl.bind("ALT + XF86MonBrightnessDown", hl.dsp.exec_cmd(Y .. " gamma lower 5"), { repeating = true, locked = true, description = "Gamma down (fine, 5%)" })
hl.bind("ALT + XF86MonBrightnessUp", hl.dsp.exec_cmd(Y .. " gamma raise 5"), { repeating = true, locked = true, description = "Gamma up (fine, 5%)" })
hl.bind(MOD .. " + Z", hl.dsp.exec_cmd(Y .. " 3d toggle"), { description = "3D room / cube workspaces on/off" })
hl.bind(MOD .. " + SHIFT + Z", hl.dsp.exec_cmd(Y .. " 3d keys"), { description = "3D room controls cheat-sheet" })

-- --- media keys: repeat + work on the lockscreen; OSD needs `ags` running ---
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ 0 && wpctl set-volume -l 1.0 @DEFAULT_AUDIO_SINK@ 5%+ && ags request -i ypsilon osd volume"), { repeating = true, locked = true, description = "Volume up" })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ 0 && wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%- && ags request -i ypsilon osd volume"), { repeating = true, locked = true, description = "Volume down" })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle && ags request -i ypsilon osd volume"), { locked = true, description = "Mute" })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl -q set 5%+ && ags request -i ypsilon osd brightness"), { repeating = true, locked = true, description = "Brightness up" })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -q set 5%- && ags request -i ypsilon osd brightness"), { repeating = true, locked = true, description = "Brightness down" })
hl.bind("SHIFT + XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ 0 && wpctl set-volume -l 1.0 @DEFAULT_AUDIO_SINK@ 1%+ && ags request -i ypsilon osd volume"), { repeating = true, locked = true, description = "Volume up (fine, 1%)" })
hl.bind("SHIFT + XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ 0 && wpctl set-volume @DEFAULT_AUDIO_SINK@ 1%- && ags request -i ypsilon osd volume"), { repeating = true, locked = true, description = "Volume down (fine, 1%)" })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true, description = "Mute microphone" })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Play / pause" })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Play / pause" })
hl.bind("XF86AudioStop", hl.dsp.exec_cmd("playerctl stop"), { locked = true, description = "Stop media" })
hl.bind(MOD .. " + CTRL + Space", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Play / pause (no media keys)" })
hl.bind(MOD .. " + CTRL + equal", hl.dsp.exec_cmd("playerctl next"), { locked = true, description = "Next track (no media keys)" })
hl.bind(MOD .. " + CTRL + minus", hl.dsp.exec_cmd("playerctl previous"), { locked = true, description = "Previous track (no media keys)" })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true, description = "Next track" })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true, description = "Previous track" })
